// Package migrate is generated by ent for schema creation and, in its hand
// written files, provides the versioned-migration runtime this project
// actually uses instead of ent's automatic Schema.Create diff-and-apply.
// Code generation only ever (re)writes migrate.go and schema.go into this
// directory by fixed name; it never scans the directory and deletes anything,
// so the hand-written files coexist safely with the generated ones, the same
// way internal/ent/embedded.go already coexists with generated files directly
// in internal/ent.
//
// The hand-written files, by what each owns:
//
//   - apply.go: the embedded migration sets and the apply loop.
//   - transaction.go: applying one migration inside its own transaction.
//   - history.go: the schema_migrations table itself.
//   - gate.go: deciding from a database's history whether this build may use it.
//   - compat.go: which migrations break the build before them (the policy).
//   - plan.go: answering what an upgrade would do, without doing it.
//
// # Many controllers, one database
//
// Any number of controllers may start against one database at the same
// instant, and every one of them runs Apply. Nothing coordinates them and
// nothing needs to. Each migration's transaction records its version FIRST,
// before running a single statement of its script, and the version is the
// table's primary key. A second starter reaching the same migration therefore
// waits on the first one's uncommitted record and then fails on it, holding
// nothing the first one needs, so there is no deadlock to break and no lock to
// leak. The loser then reads the history again, finds the version recorded,
// and carries on with the next migration.
//
// That is the reasoning internal/tlscert's Ensure applies to certificates,
// consumed rather than re-invented: load, attempt, load again, and treat a
// write that lost as news that somebody else already did the work. The one
// deliberate difference is that a loser here waits for the winner's
// transaction instead of never waiting at all, because a migration is
// expensive and two runs of it are not interchangeable, which is exactly the
// case FAILURE_PATTERNS.md #134 says to serialize. The wait is on the
// database's own record of the work, so a winner that dies releases it the
// moment its transaction does.
package migrate

import (
	"context"
	"database/sql"
	"embed"
	"fmt"
	"io/fs"
	"sort"
)

// sqliteMigrations embeds every committed SQLite migration file so the
// built binary carries them, needing no external file at runtime.
//
//go:embed migrations/sqlite/*.sql
var sqliteMigrations embed.FS

// postgresMigrations embeds every committed Postgres migration file, for
// the same reason.
//
// This set starts at one squashed 0001_initial.sql rather than mirroring
// SQLite's four-file history, and that is correct rather than a lost
// history: a migration ledger is per database, ent can only ever diff
// against the schema it desires today, and no Postgres database had ever
// been migrated by this project when the set began. The two dialects diverge
// in file count here and stay in lockstep from here on, since every later
// schema change is generated for both.
//
//go:embed migrations/postgres/*.sql
var postgresMigrations embed.FS

// migrationSource pairs an embedded filesystem with the directory inside
// it holding one dialect's migration files, plus the statements whose text
// genuinely differs between dialects.
type migrationSource struct {
	// dialect is the driver name this source is registered under, which
	// is also the key its contract declarations live under (compat.go).
	dialect string

	fsys embed.FS
	dir  string

	// insertVersion is the parameterized statement recording one
	// migration as applied, taking its name, the time and its compatibility
	// floor. It lives here, beside the dialect it belongs to, because
	// placeholder syntax is dialect-specific and database/sql does not
	// normalize it: lib/pq rejects "?" outright ("pq: syntax error at or
	// near ,"), and it rejects it inside the same transaction as the
	// migration's own DDL, so the DDL rolls back too and the failure reads
	// as broken DDL rather than as a wrong placeholder.
	insertVersion string

	// historyTableCount counts tables named schema_migrations: one once the
	// history exists, zero before.
	historyTableCount string

	// primaryKeyColumns lists the columns of schema_migrations' primary key,
	// in key order. The catalogs that answer it are dialect specific.
	primaryKeyColumns string

	// floorColumnCount counts schema_migrations columns named
	// compatible_from: one once the floor column exists, zero before.
	floorColumnCount string

	// claimPrelude is run inside each migration's transaction before its
	// version is recorded, and prelude after it and before its script (see
	// transaction.go for each setting and why the order matters).
	claimPrelude []string
	prelude      []string

	// suspendForeignKeys says whether this dialect needs enforcement
	// turned off around a migration, and its integrity checked again
	// before the migration is allowed to commit. It is true for SQLite
	// alone: see applyOne for what rebuilding a table costs there.
	// Postgres alters a constraint in place, inside transactional DDL, so
	// it needs neither half of this.
	suspendForeignKeys bool

	// waitForWriters says whether this dialect's busy timeout has to be
	// raised while a migration runs. It is true for SQLite alone, whose
	// ordinary five-second wait for a writer is shorter than a table rebuild
	// on a large database can take (see applyOne).
	waitForWriters bool
}

// migrationSources maps a driver dialect name (entgo.io/ent/dialect's
// SQLite/Postgres/MySQL constants) to its embedded migration files.
//
// Both dialects' files are produced by internal/ent/migrate/gen, never
// hand written, and parity_test.go asserts the two sets stay in step, so
// regenerating one dialect and forgetting the other fails the build
// instead of drifting silently.
var migrationSources = map[string]migrationSource{
	"sqlite3": {
		dialect:            "sqlite3",
		fsys:               sqliteMigrations,
		dir:                "migrations/sqlite",
		insertVersion:      `INSERT INTO schema_migrations (version, applied_at, compatible_from) VALUES (?, ?, ?)`,
		historyTableCount:  `SELECT count(*) FROM sqlite_master WHERE type = 'table' AND name = 'schema_migrations'`,
		primaryKeyColumns:  `SELECT name FROM pragma_table_info('schema_migrations') WHERE pk > 0 ORDER BY pk`,
		floorColumnCount:   `SELECT count(*) FROM pragma_table_info('schema_migrations') WHERE name = 'compatible_from'`,
		suspendForeignKeys: true,
		waitForWriters:     true,
	},
	"postgres": {
		dialect:           "postgres",
		fsys:              postgresMigrations,
		dir:               "migrations/postgres",
		insertVersion:     `INSERT INTO schema_migrations (version, applied_at, compatible_from) VALUES ($1, $2, $3)`,
		historyTableCount: `SELECT count(*) FROM pg_catalog.pg_class WHERE oid = to_regclass('schema_migrations')`,
		// to_regclass resolves the unqualified name through the search path,
		// exactly as every other statement in this package does, so this
		// reads the key of the same table the migrations write.
		primaryKeyColumns: `SELECT a.attname FROM pg_catalog.pg_constraint c
			JOIN pg_catalog.pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
			WHERE c.contype = 'p' AND c.conrelid = to_regclass('schema_migrations')
			ORDER BY array_position(c.conkey, a.attnum)`,
		floorColumnCount: `SELECT count(*) FROM pg_catalog.pg_attribute
			WHERE attrelid = to_regclass('schema_migrations') AND attname = 'compatible_from'
			AND attnum > 0 AND NOT attisdropped`,
		claimPrelude: postgresClaimPrelude,
		prelude:      postgresPrelude,
	},
}

// Options adjusts what Apply accepts.
type Options struct {
	// AllowNewerWithinWindow lets a database that a newer build already
	// migrated further be used, when every migration this build does not
	// know recorded a compatibility floor this build reaches. Nothing is
	// applied to such a database.
	//
	// Only a long-running server and its own admin commands set this. Restore
	// and every offline tool leave it off: they must never proceed against a
	// schema they were not built for.
	AllowNewerWithinWindow bool

	// RefuseToUpgrade migrates a database that holds no history yet (a new
	// install) but refuses, with ErrUpgradeRequired, one that holds history
	// and has migrations of this build pending.
	//
	// Admin commands set it. Upgrading is the server's job and compose's
	// make up, which takes a backup first; a password reset run with a newer
	// binary must not be what upgrades a database behind that backup's back.
	RefuseToUpgrade bool
}

// Outcome reports what one Apply call found and did.
type Outcome struct {
	// Applied lists the migrations this call applied, in order.
	Applied []string

	// AppliedElsewhere lists the migrations this call reached and found that
	// another starter had applied first. Seeing one is the ordinary result of
	// several controllers starting together, not a warning.
	AppliedElsewhere []string

	// Newer lists the recorded migrations this build does not know. It is
	// only ever non-empty when AllowNewerWithinWindow was set.
	Newer []string

	// Floor is the oldest migration a build must know to serve this database,
	// when Newer is non-empty.
	Floor string
}

// Apply brings db up to the latest schema version for dialectName by
// executing every embedded migration file for that dialect not already
// recorded as applied, in filename order, each inside its own transaction.
// It is the versioned-migration replacement for ent's automatic
// Schema.Create.
//
// Apply is also the startup schema-version gate: it fails closed, rather
// than silently continuing, if db already has a migration recorded that
// this binary's embedded set does not recognize (an older binary running
// against a database a newer binary already migrated further), or if the
// recorded history has a gap (a partially migrated or tampered database).
// ApplyWith can relax the first of those within the compatibility window.
func Apply(ctx context.Context, dialectName string, db *sql.DB) error {
	_, err := ApplyWith(ctx, dialectName, db, Options{})
	return err
}

// ApplyWith is Apply with options, reporting what it found and did.
func ApplyWith(ctx context.Context, dialectName string, db *sql.DB, opts Options) (Outcome, error) {
	src, ok := migrationSources[dialectName]
	if !ok {
		return Outcome{}, fmt.Errorf("migrate: no embedded migrations for dialect %q", dialectName)
	}
	names, err := migrationNames(src)
	if err != nil {
		return Outcome{}, err
	}
	mode := gateStrict
	if opts.AllowNewerWithinWindow {
		mode = gateWithinWindow
	}
	if opts.RefuseToUpgrade {
		plan, err := Inspect(ctx, dialectName, db)
		if err != nil {
			return Outcome{}, err
		}
		if plan.Verdict == VerdictPending {
			return Outcome{}, fmt.Errorf("%w (it records %s, this build ends at %s)", ErrUpgradeRequired, plan.DatabaseHead, plan.BuildHead)
		}
	}
	return applyPending(ctx, db, src, names, "", mode)
}

// applyPending applies every migration in names that db has not recorded, in
// order, stopping after the file named stopAfter.
//
// Every pass round the loop starts by reading the history again, and every
// decision is the gate's, made from that fresh read. So a migration another
// starter committed while this one was working is simply not pending on the
// next pass, a newer build that raced ahead is refused on the next pass, and
// the loop cannot spin: each pass either returns or leaves one more migration
// recorded, by this call or by somebody else.
//
// stopAfter exists for the tests, which have to build a database at one past
// version, put rows in it, and only then apply the next migration: that is the
// only way to prove an upgrade preserves data, and it cannot be done if the
// only entry point migrates all the way to the newest version in one call. An
// empty stopAfter applies everything, which is what Apply itself asks for.
func applyPending(ctx context.Context, db *sql.DB, src migrationSource, names []string, stopAfter string, mode gateMode) (Outcome, error) {
	var out Outcome

	history, err := prepareHistory(ctx, db, src)
	if err != nil {
		return out, err
	}
	for {
		gate, err := checkGate(names, history, mode)
		if err != nil {
			return out, err
		}
		out.Newer, out.Floor = gate.newer, gate.floor
		if len(gate.pending) == 0 || recorded(history, stopAfter) {
			return out, nil
		}

		name := gate.pending[0]
		script, err := fs.ReadFile(src.fsys, src.dir+"/"+name)
		if err != nil {
			return out, fmt.Errorf("migrate: reading %s: %w", name, err)
		}
		attemptErr := applyOne(ctx, db, src, name, string(script), floorAfter(src.dialect, names, name))

		// Load again, whatever happened. After a success this is what the
		// next pass decides from; after a failure it is the only way to
		// tell losing to another starter, which leaves the version
		// recorded, from a migration that genuinely failed, which does not.
		history, err = readHistory(ctx, db, src)
		if err != nil {
			if attemptErr != nil {
				return out, attemptErr
			}
			return out, err
		}
		switch {
		case attemptErr == nil:
			out.Applied = append(out.Applied, name)
		case recorded(history, name):
			out.AppliedElsewhere = append(out.AppliedElsewhere, name)
		default:
			return out, attemptErr
		}
	}
}

// recorded reports whether history holds the named migration. An empty name
// is never recorded, which is what lets applyPending pass an empty stopAfter.
func recorded(history []appliedRow, name string) bool {
	if name == "" {
		return false
	}
	for _, row := range history {
		if row.version == name {
			return true
		}
	}
	return false
}

// migrationNames lists a dialect's embedded migration filenames in
// ascending (application) order. Filenames are numbered
// (0001_initial.sql, 0002_..., ...), so a plain lexicographic sort is the
// correct application order.
func migrationNames(src migrationSource) ([]string, error) {
	entries, err := fs.ReadDir(src.fsys, src.dir)
	if err != nil {
		return nil, fmt.Errorf("migrate: reading embedded migration directory %q: %w", src.dir, err)
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)
	return names, nil
}
